func Fold[E, A any](seq iter.Seq[E], init A, f func(A, E) A) A {
    for v := range seq {                 // push iterator
        init = f(init, v)
    }
    return init
}

// early exit: returning from the range body stops the producer
func Any[E any](seq iter.Seq[E], pred func(E) bool) bool {
    for v := range seq {
        if pred(v) {
            return true                  // yield returns false -> producer stops
        }
    }
    return false
}
